{"metadata":{"kernel_spec":{"name":"SQL","language":"sql","display_name":"SQL"},"language_info":{"name":"sql","version":""}},"nbformat":4,"nbformat_minor":2,"cells":[{"cell_type":"markdown","source":["# [dbo].[prc_Audit_Inventaire]"],"metadata":{"urn":"Server[@Name='AMINEJB\\SQLEXPRESS']/Database[@Name='Gestion_Stock']/StoredProcedure[@Name='prc_Audit_Inventaire' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["USE [Gestion_Stock]\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='AMINEJB\\SQLEXPRESS']/Database[@Name='Gestion_Stock']/StoredProcedure[@Name='prc_Audit_Inventaire' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[prc_Audit_Inventaire]    Script Date: 20/07/2026 02:09:28 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","CREATE PROCEDURE [dbo].[prc_Audit_Inventaire]\r\n    @Action NVARCHAR(20),\r\n    @id_inventaire INT,\r\n    @date_inventaire DATETIME = NULL,\r\n    @remarque VARCHAR(50) = NULL,\r\n    @id_entrepot INT = NULL,\r\n    @id_produit INT = NULL,\r\n    @id_utilisateur INT\r\nAS\r\nBEGIN\r\n    SET NOCOUNT ON;\r\n\r\n    DECLARE @nom_utilisateur NVARCHAR(80);\r\n    SELECT @nom_utilisateur = nom_utilisateur \r\n    FROM Utilisateur \r\n    WHERE id_utilisateur = @id_utilisateur;\r\n\r\n    INSERT INTO Audit (\r\n        id_cible, nom_table, type_op,\r\n        Date_op, id_utilisateur, id_utilisateur_connecte, nom_utilisateur,\r\n        ancienne_valeur, nouvelle_valeur\r\n    )\r\n    VALUES (\r\n        'id inventaire :' + CAST(@id_inventaire AS NVARCHAR(80)),\r\n        'Inventaire',\r\n        CASE \r\n            WHEN @Action = 'INSERT' THEN 'Insertion'\r\n            WHEN @Action = 'UPDATE' THEN 'Modification'\r\n            WHEN @Action = 'DELETE' THEN 'Suppression'\r\n        END,\r\n        GETDATE(),\r\n        @id_utilisateur,\r\n        @id_utilisateur,\r\n        @nom_utilisateur,\r\n        CASE \r\n            WHEN @Action = 'UPDATE' OR @Action = 'DELETE' THEN\r\n                'date :' + ISNULL(CONVERT(NVARCHAR(80), @date_inventaire), '') +\r\n                ' remarque :' + ISNULL(@remarque, '') +\r\n                ' entrepot :' + ISNULL(CAST(@id_entrepot AS NVARCHAR(80)), '') +\r\n                ' produit :' + ISNULL(CAST(@id_produit AS NVARCHAR(80)), '')\r\n            ELSE NULL\r\n        END,\r\n        CASE \r\n            WHEN @Action = 'INSERT' OR @Action = 'UPDATE' THEN\r\n                'date :' + ISNULL(CONVERT(NVARCHAR(80), @date_inventaire), '') +\r\n                ' remarque :' + ISNULL(@remarque, '') +\r\n                ' entrepot :' + ISNULL(CAST(@id_entrepot AS NVARCHAR(80)), '') +\r\n                ' produit :' + ISNULL(CAST(@id_produit AS NVARCHAR(80)), '')\r\n            ELSE NULL\r\n        END\r\n    );\r\nEND;\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='AMINEJB\\SQLEXPRESS']/Database[@Name='Gestion_Stock']/StoredProcedure[@Name='prc_Audit_Inventaire' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[prc_Audit_LigneAchat]"],"metadata":{"urn":"Server[@Name='AMINEJB\\SQLEXPRESS']/Database[@Name='Gestion_Stock']/StoredProcedure[@Name='prc_Audit_LigneAchat' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[prc_Audit_LigneAchat]    Script Date: 20/07/2026 02:09:28 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","CREATE PROCEDURE [dbo].[prc_Audit_LigneAchat]\r\n    @Action NVARCHAR(20),\r\n    @id_produit INT,\r\n    @id_commande INT,\r\n    @id_lot INT,\r\n    @Quantite INT = NULL,\r\n    @Prix_achat DECIMAL(18,2) = NULL,\r\n    @Ancien_Quantite INT = NULL,\r\n    @Ancien_Prix_achat DECIMAL(18,2) = NULL,\r\n    @id_utilisateur INT\r\nAS\r\nBEGIN\r\n    SET NOCOUNT ON;\r\n\r\n    DECLARE @nom_utilisateur NVARCHAR(80);\r\n    SELECT @nom_utilisateur = nom_utilisateur \r\n    FROM Utilisateur \r\n    WHERE id_utilisateur = @id_utilisateur;\r\n\r\n    INSERT INTO Audit (\r\n        id_cible, nom_table, type_op,\r\n        Date_op, id_utilisateur, id_utilisateur_connecte, nom_utilisateur,\r\n        ancienne_valeur, nouvelle_valeur\r\n    )\r\n    VALUES (\r\n        'id produit :' + CAST(@id_produit AS NVARCHAR(80)) +\r\n        ' id commande :' + CAST(@id_commande AS NVARCHAR(80)) +\r\n        ' id lot :' + CAST(@id_lot AS NVARCHAR(80)),\r\n        'Ligne Achat',\r\n        CASE \r\n            WHEN @Action = 'INSERT' THEN 'Insertion'\r\n            WHEN @Action = 'UPDATE' THEN 'Modification'\r\n            WHEN @Action = 'DELETE' THEN 'Suppression'\r\n        END,\r\n        GETDATE(),\r\n        @id_utilisateur,\r\n        @id_utilisateur,\r\n        @nom_utilisateur,\r\n        CASE \r\n            WHEN @Action = 'UPDATE' THEN\r\n                'Quantite :' + ISNULL(CAST(@Ancien_Quantite AS NVARCHAR(80)), '') +\r\n                ' Prix_achat :' + ISNULL(CAST(@Ancien_Prix_achat AS NVARCHAR(80)), '')\r\n            WHEN @Action = 'DELETE' THEN\r\n                'Quantite :' + ISNULL(CAST(@Quantite AS NVARCHAR(80)), '') +\r\n                ' Prix_achat :' + ISNULL(CAST(@Prix_achat AS NVARCHAR(80)), '')\r\n            ELSE NULL\r\n        END,\r\n        CASE \r\n            WHEN @Action = 'INSERT' OR @Action = 'UPDATE' THEN\r\n                'Quantite :' + ISNULL(CAST(@Quantite AS NVARCHAR(80)), '') +\r\n                ' Prix_achat :' + ISNULL(CAST(@Prix_achat AS NVARCHAR(80)), '')\r\n            ELSE NULL\r\n        END\r\n    );\r\nEND;\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='AMINEJB\\SQLEXPRESS']/Database[@Name='Gestion_Stock']/StoredProcedure[@Name='prc_Audit_LigneAchat' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[prc_Audit_LigneInventaire]"],"metadata":{"urn":"Server[@Name='AMINEJB\\SQLEXPRESS']/Database[@Name='Gestion_Stock']/StoredProcedure[@Name='prc_Audit_LigneInventaire' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[prc_Audit_LigneInventaire]    Script Date: 20/07/2026 02:09:28 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","CREATE PROCEDURE [dbo].[prc_Audit_LigneInventaire]\r\n    @Action NVARCHAR(20),\r\n    @id_produit INT,\r\n    @id_inventaire INT,\r\n    @stock_theorique INT = NULL,\r\n    @stock_reel INT = NULL,\r\n    @Ancien_stock_theorique INT = NULL,\r\n    @Ancien_stock_reel INT = NULL,\r\n    @id_utilisateur INT\r\nAS\r\nBEGIN\r\n    SET NOCOUNT ON;\r\n\r\n    DECLARE @nom_utilisateur NVARCHAR(80);\r\n    SELECT @nom_utilisateur = nom_utilisateur \r\n    FROM Utilisateur \r\n    WHERE id_utilisateur = @id_utilisateur;\r\n\r\n    INSERT INTO Audit (\r\n        id_cible, nom_table, type_op,\r\n        Date_op, id_utilisateur, id_utilisateur_connecte, nom_utilisateur,\r\n        ancienne_valeur, nouvelle_valeur\r\n    )\r\n    VALUES (\r\n        'id inventaire :' + CAST(@id_inventaire AS NVARCHAR(80)) +\r\n        ' id produit :' + CAST(@id_produit AS NVARCHAR(80)),\r\n        'Ligne_inventaire',\r\n        CASE \r\n            WHEN @Action = 'INSERT' THEN 'Insertion'\r\n            WHEN @Action = 'UPDATE' THEN 'Modification'\r\n            WHEN @Action = 'DELETE' THEN 'Suppression'\r\n        END,\r\n        GETDATE(),\r\n        @id_utilisateur,\r\n        @id_utilisateur,\r\n        @nom_utilisateur,\r\n        CASE \r\n            WHEN @Action = 'UPDATE' THEN \r\n                'stock théorique :' + ISNULL(CAST(@Ancien_stock_theorique AS NVARCHAR(80)), '') +\r\n                ' stock réel :' + ISNULL(CAST(@Ancien_stock_reel AS NVARCHAR(80)), '')\r\n            WHEN @Action = 'DELETE' THEN \r\n                'stock théorique :' + ISNULL(CAST(@stock_theorique AS NVARCHAR(80)), '') +\r\n                ' stock réel :' + ISNULL(CAST(@stock_reel AS NVARCHAR(80)), '')\r\n            ELSE NULL\r\n        END,\r\n        CASE \r\n            WHEN @Action = 'INSERT' THEN \r\n                'stock théorique :' + ISNULL(CAST(@stock_theorique AS NVARCHAR(80)), '') +\r\n                ' stock réel :' + ISNULL(CAST(@stock_reel AS NVARCHAR(80)), '')\r\n            WHEN @Action = 'UPDATE' THEN \r\n                'stock théorique :' + ISNULL(CAST(@stock_theorique AS NVARCHAR(80)), '') +\r\n                ' stock réel :' + ISNULL(CAST(@stock_reel AS NVARCHAR(80)), '')\r\n            ELSE NULL\r\n        END\r\n    );\r\nEND;\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='AMINEJB\\SQLEXPRESS']/Database[@Name='Gestion_Stock']/StoredProcedure[@Name='prc_Audit_LigneInventaire' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[prc_Audit_LigneStock]"],"metadata":{"urn":"Server[@Name='AMINEJB\\SQLEXPRESS']/Database[@Name='Gestion_Stock']/StoredProcedure[@Name='prc_Audit_LigneStock' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[prc_Audit_LigneStock]    Script Date: 20/07/2026 02:09:28 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","CREATE PROCEDURE [dbo].[prc_Audit_LigneStock]\r\n    @Action NVARCHAR(20),\r\n    @id_produit INT,\r\n    @id_emplacement INT,\r\n    @Quantite INT = NULL,\r\n    @Ancien_Quantite INT = NULL,\r\n    @id_utilisateur INT\r\nAS\r\nBEGIN\r\n    SET NOCOUNT ON;\r\n\r\n    DECLARE @nom_utilisateur NVARCHAR(80);\r\n    SELECT @nom_utilisateur = nom_utilisateur \r\n    FROM Utilisateur \r\n    WHERE id_utilisateur = @id_utilisateur;\r\n\r\n    INSERT INTO Audit (\r\n        id_cible, nom_table, type_op,\r\n        Date_op, id_utilisateur, id_utilisateur_connecte, nom_utilisateur,\r\n        ancienne_valeur, nouvelle_valeur\r\n    )\r\n    VALUES (\r\n        'id produit :' + CAST(@id_produit AS NVARCHAR(80)) +\r\n        ' id emplacement :' + CAST(@id_emplacement AS NVARCHAR(80)),\r\n        'Ligne Stock',\r\n        CASE \r\n            WHEN @Action = 'INSERT' THEN 'Insertion'\r\n            WHEN @Action = 'UPDATE' THEN 'Modification'\r\n            WHEN @Action = 'DELETE' THEN 'Suppression'\r\n        END,\r\n        GETDATE(),\r\n        @id_utilisateur,\r\n        @id_utilisateur,\r\n        @nom_utilisateur,\r\n        CASE \r\n            WHEN @Action = 'UPDATE' THEN 'Quantite :' + ISNULL(CAST(@Ancien_Quantite AS NVARCHAR(80)), '')\r\n            WHEN @Action = 'DELETE' THEN 'Quantite :' + ISNULL(CAST(@Quantite AS NVARCHAR(80)), '')\r\n            ELSE NULL\r\n        END,\r\n        CASE \r\n            WHEN @Action = 'INSERT' OR @Action = 'UPDATE' THEN 'Quantite :' + ISNULL(CAST(@Quantite AS NVARCHAR(80)), '')\r\n            ELSE NULL\r\n        END\r\n    );\r\nEND;\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='AMINEJB\\SQLEXPRESS']/Database[@Name='Gestion_Stock']/StoredProcedure[@Name='prc_Audit_LigneStock' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[prc_Audit_LigneVente]"],"metadata":{"urn":"Server[@Name='AMINEJB\\SQLEXPRESS']/Database[@Name='Gestion_Stock']/StoredProcedure[@Name='prc_Audit_LigneVente' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[prc_Audit_LigneVente]    Script Date: 20/07/2026 02:09:28 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","CREATE PROCEDURE [dbo].[prc_Audit_LigneVente]  \r\n    @Action NVARCHAR(20),  \r\n    @id_vente INT,  \r\n    @id_produit INT,  \r\n    @id_lot INT,  \r\n    @Prix_Vente DECIMAL(18,2) = NULL,  \r\n    @Quantite INT = NULL,  \r\n    @Ancien_Prix DECIMAL(18,2) = NULL,  \r\n    @Ancienne_Quantite INT = NULL,  \r\n    @id_utilisateur INT  \r\nAS  \r\nBEGIN  \r\n    SET NOCOUNT ON;  \r\n  \r\n    DECLARE @nom_utilisateur NVARCHAR(80);  \r\n    SELECT @nom_utilisateur = nom_utilisateur  \r\n    FROM Utilisateur  \r\n    WHERE id_utilisateur = @id_utilisateur;  \r\n  \r\n    INSERT INTO Audit (  \r\n        id_cible, nom_table, type_op,  \r\n        Date_op, id_utilisateur, id_utilisateur_connecte, nom_utilisateur,  \r\n        ancienne_valeur, nouvelle_valeur  \r\n    )  \r\n    VALUES (  \r\n        'id vente :' + CAST(@id_vente AS NVARCHAR(80)) +  \r\n        ' id produit :' + CAST(@id_produit AS NVARCHAR(80)) +  \r\n        ' id lot :' + CAST(@id_lot AS NVARCHAR(80)),  \r\n        'Ligne Vente',  \r\n        CASE   \r\n            WHEN @Action = 'INSERT' THEN 'Insertion'  \r\n            WHEN @Action = 'UPDATE' THEN 'Modification'  \r\n            WHEN @Action = 'DELETE' THEN 'Suppression'  \r\n        END,  \r\n        GETDATE(),  \r\n        @id_utilisateur,  \r\n        @id_utilisateur,  \r\n        @nom_utilisateur,  \r\n        CASE   \r\n            WHEN @Action = 'UPDATE' THEN   \r\n                'Prix vente :' + ISNULL(CAST(@Ancien_Prix AS NVARCHAR(80)), '') +  \r\n                ' Quantite :' + ISNULL(CAST(@Ancienne_Quantite AS NVARCHAR(80)), '')  \r\n            WHEN @Action = 'DELETE' THEN   \r\n                'Prix vente :' + ISNULL(CAST(@Prix_Vente AS NVARCHAR(80)), '') +  \r\n                ' Quantite :' + ISNULL(CAST(@Quantite AS NVARCHAR(80)), '')  \r\n            ELSE NULL  \r\n        END,  \r\n        CASE   \r\n            WHEN @Action = 'INSERT' THEN   \r\n                'Prix vente :' + ISNULL(CAST(@Prix_Vente AS NVARCHAR(80)), '') +  \r\n                ' Quantite :' + ISNULL(CAST(@Quantite AS NVARCHAR(80)), '')  \r\n            WHEN @Action = 'UPDATE' THEN   \r\n                'Prix vente :' + ISNULL(CAST(@Prix_Vente AS NVARCHAR(80)), '') +  \r\n                ' Quantite :' + ISNULL(CAST(@Quantite AS NVARCHAR(80)), '')  \r\n            ELSE NULL  \r\n        END  \r\n    );  \r\nEND;\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='AMINEJB\\SQLEXPRESS']/Database[@Name='Gestion_Stock']/StoredProcedure[@Name='prc_Audit_LigneVente' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[prc_Audit_Lot]"],"metadata":{"urn":"Server[@Name='AMINEJB\\SQLEXPRESS']/Database[@Name='Gestion_Stock']/StoredProcedure[@Name='prc_Audit_Lot' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[prc_Audit_Lot]    Script Date: 20/07/2026 02:09:28 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","CREATE PROCEDURE [dbo].[prc_Audit_Lot]\r\n    @Action NVARCHAR(20),           -- 'INSERT', 'UPDATE', 'DELETE'\r\n    @id_lot INT,\r\n    @id_produit INT,\r\n    @date_fabrication DATETIME = NULL,\r\n    @date_peremption DATETIME = NULL,\r\n    @Ancienne_date_fabrication DATETIME = NULL,\r\n    @Ancienne_date_peremption DATETIME = NULL,\r\n    @id_utilisateur INT\r\nAS\r\nBEGIN\r\n    SET NOCOUNT ON;\r\n\r\n    DECLARE @nom_utilisateur NVARCHAR(80);\r\n    SELECT @nom_utilisateur = nom_utilisateur \r\n    FROM Utilisateur \r\n    WHERE id_utilisateur = @id_utilisateur;\r\n\r\n    INSERT INTO Audit (\r\n        id_cible, nom_table, type_op,\r\n        Date_op, id_utilisateur, id_utilisateur_connecte, nom_utilisateur,\r\n        ancienne_valeur, nouvelle_valeur\r\n    )\r\n    VALUES (\r\n        'id Lot :' + CAST(@id_lot AS NVARCHAR(80)) + ' id produit :' + CAST(@id_produit AS NVARCHAR(80)),\r\n        'Lot',\r\n        CASE \r\n            WHEN @Action = 'INSERT' THEN 'Insertion'\r\n            WHEN @Action = 'UPDATE' THEN 'Modification'\r\n            WHEN @Action = 'DELETE' THEN 'Suppression'\r\n        END,\r\n        GETDATE(),\r\n        @id_utilisateur,\r\n        @id_utilisateur,\r\n        @nom_utilisateur,\r\n        CASE \r\n            WHEN @Action = 'UPDATE' THEN \r\n                'date fabrication :' + ISNULL(CONVERT(NVARCHAR(80), @Ancienne_date_fabrication, 120), '') +\r\n                ' date peremption :' + ISNULL(CONVERT(NVARCHAR(80), @Ancienne_date_peremption, 120), '')\r\n            WHEN @Action = 'DELETE' THEN \r\n                'date fabrication :' + ISNULL(CONVERT(NVARCHAR(80), @date_fabrication, 120), '') +\r\n                ' date peremption :' + ISNULL(CONVERT(NVARCHAR(80), @date_peremption, 120), '')\r\n            ELSE NULL\r\n        END,\r\n        CASE \r\n            WHEN @Action = 'INSERT' THEN \r\n                'date fabrication :' + ISNULL(CONVERT(NVARCHAR(80), @date_fabrication, 120), '') +\r\n                ' date peremption :' + ISNULL(CONVERT(NVARCHAR(80), @date_peremption, 120), '')\r\n            WHEN @Action = 'UPDATE' THEN \r\n                'date fabrication :' + ISNULL(CONVERT(NVARCHAR(80), @date_fabrication, 120), '') +\r\n                ' date peremption :' + ISNULL(CONVERT(NVARCHAR(80), @date_peremption, 120), '')\r\n            ELSE NULL\r\n        END\r\n    );\r\nEND;\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='AMINEJB\\SQLEXPRESS']/Database[@Name='Gestion_Stock']/StoredProcedure[@Name='prc_Audit_Lot' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[prc_Audit_Paiement]"],"metadata":{"urn":"Server[@Name='AMINEJB\\SQLEXPRESS']/Database[@Name='Gestion_Stock']/StoredProcedure[@Name='prc_Audit_Paiement' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[prc_Audit_Paiement]    Script Date: 20/07/2026 02:09:28 ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","CREATE PROCEDURE [dbo].[prc_Audit_Paiement]\r\n    @Action NVARCHAR(20),\r\n    @id_paiement INT,\r\n    @id_vente INT,\r\n    @date_paiement DATETIME = NULL,\r\n    @mode_paiement NVARCHAR(50) = NULL,\r\n    @Ancienne_date DATETIME = NULL,\r\n    @Ancien_mode NVARCHAR(50) = NULL,\r\n    @id_utilisateur INT\r\nAS\r\nBEGIN\r\n    SET NOCOUNT ON;\r\n\r\n    DECLARE @nom_utilisateur NVARCHAR(80);\r\n    SELECT @nom_utilisateur = nom_utilisateur \r\n    FROM Utilisateur \r\n    WHERE id_utilisateur = @id_utilisateur;\r\n\r\n    INSERT INTO Audit (\r\n        id_cible, nom_table, type_op,\r\n        Date_op, id_utilisateur, id_utilisateur_connecte, nom_utilisateur,\r\n        ancienne_valeur, nouvelle_valeur\r\n    )\r\n    VALUES (\r\n        'id paiement :' + CAST(@id_paiement AS NVARCHAR(80)) +\r\n        ' id vente :' + CAST(@id_vente AS NVARCHAR(80)),\r\n        'Paiement',\r\n        CASE \r\n            WHEN @Action = 'INSERT' THEN 'Insertion'\r\n            WHEN @Action = 'UPDATE' THEN 'Modification'\r\n            WHEN @Action = 'DELETE' THEN 'Suppression'\r\n        END,\r\n        GETDATE(),\r\n        @id_utilisateur,\r\n        @id_utilisateur,\r\n        @nom_utilisateur,\r\n        CASE \r\n            WHEN @Action = 'UPDATE' THEN \r\n                'date paiement :' + ISNULL(CONVERT(NVARCHAR(80), @Ancienne_date), '') +\r\n                ' mode paiement :' + ISNULL(@Ancien_mode, '')\r\n            WHEN @Action = 'DELETE' THEN \r\n                'date paiement :' + ISNULL(CONVERT(NVARCHAR(80), @date_paiement), '') +\r\n                ' mode paiement :' + ISNULL(@mode_paiement, '')\r\n            ELSE NULL\r\n        END,\r\n        CASE \r\n            WHEN @Action = 'INSERT' THEN \r\n                'date paiement :' + ISNULL(CONVERT(NVARCHAR(80), @date_paiement), '') +\r\n                ' mode paiement :' + ISNULL(@mode_paiement, '')\r\n            WHEN @Action = 'UPDATE' THEN \r\n                'date paiement :' + ISNULL(CONVERT(NVARCHAR(80), @date_paiement), '') +\r\n                ' mode paiement :' + ISNULL(@mode_paiement, '')\r\n            ELSE NULL\r\n        END\r\n    );\r\nEND;\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='AMINEJB\\SQLEXPRESS']/Database[@Name='Gestion_Stock']/StoredProcedure[@Name='prc_Audit_Paiement' and @Schema='dbo']","object_type":"StoredProcedure"}}]}